import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * helix-core's fixtures (stories rule 6): the vendored KYA-OS conformance
 * suite under `kya-os/` and the cross-language `kya-os-helix/*.json` set
 * generated by helix-core. Read from the sibling checkout
 * (`../../helix-core/fixtures` from the helix-sdk-js workspace root), or from the directory
 * `HELIX_CORE_FIXTURES_DIR` names. Tests that need them skip, loudly, when
 * neither exists, the way helix-sdk-py's do.
 */
export const coreFixturesDir: string =
  process.env['HELIX_CORE_FIXTURES_DIR'] ?? resolve(fileURLToPath(new URL('../../../', import.meta.url)), '../../helix-core/fixtures');

export const vectorsDir = join(coreFixturesDir, 'kya-os/conformance/vectors');

export const haveCoreFixtures = existsSync(join(coreFixturesDir, 'kya-os-helix/jcs.json'));

export const fixtureSkipReason = `helix-core fixtures not found at ${coreFixturesDir}: check out helix-core beside helix-sdk-js or set HELIX_CORE_FIXTURES_DIR`;

export function loadFixture<T>(relative: string): T {
  return JSON.parse(readFileSync(join(coreFixturesDir, relative), 'utf8')) as T;
}

export interface Vector {
  id: string;
  expected: 'pass' | 'fail';
  reason?: string;
  input: Record<string, any>;
}

export function vectors(file: string): Vector[] {
  return loadFixture<{ version: string; vectors: Vector[] }>(`kya-os/conformance/vectors/${file}`).vectors;
}

export function jwsPayload(jws: string): Record<string, unknown> {
  return JSON.parse(Buffer.from(jws.split('.')[1]!, 'base64url').toString('utf8')) as Record<string, unknown>;
}
